window.RISHU_REQUIREMENTS_CSV = "教育区分,科目区分,最低必要単位,追加条件\n教養教育,アカデミックスキル,10,必修10\n教養教育,ライフデザイン,2,必修2\n教養教育,思想と論理,2,選択2\n教養教育,沖縄理解科目,2,選択2\n教養教育,健康スポーツ,2,選択2\n教養教育,外国語,6,必修6\n教養教育,国際理解,2,選択2\n教養教育,人文科学,2,選択2\n教養教育,社会科学,2,選択2\n教養教育,自然科学,2,必修2\n専門教育,専門基礎教育科目,20,必修16・選択4\n専門教育,専門発展科目,30,選択30\n専門教育,専門応用科目,8,選択8\n専門教育,専門総合科目,14,必修8・選択6\n自由選択,自由選択科目,20,選択20\n";
window.RishuBackend = (() => {
  const data = window.RISHU_BACKEND_SNAPSHOT;
  let promise = null, source = '同梱データ';
  const alias = {
    '情報セキュリティー':'情報セキュリティ',
    'AIデータサイエンスⅠ':'AI・データサイエンスI',
    'AIデータサイエンスⅡ':'AI・データサイエンスⅡ',
    '健康ビッグデータ':'健康ビックデータ',
    '臨床医学および医療用語':'臨床医学総論及び医療用語',
    'システム開発技術(IoT)':'システム開発技術（IoT）',
    '国際統計分類I':'国際統計分類Ⅰ'
  };
  const simple = x => String(x||'').normalize('NFKC').replace(/[\s\u3000・（）()\-]/g,'').replace(/および/g,'及び').toLowerCase();
  let courseNameMap = new Map(data.courses.map(c=>[simple(c.course_name),c.course_name]));
  const byName = () => courseNameMap;
  function canonicalName(value){
    const original = String(value||'').trim();
    return byName().get(simple(alias[original]||original))||original;
  }
  function validate(payload){
    for(const key of ['courses','jobs','qualifications','job_courses','qualification_courses','job_qualifications'])
      if(!Array.isArray(payload?.[key])) throw Error('APIの形式が一致していません：'+key);
    if(payload.courses.some(c=>!c.course_id||!c.course_name||!Number.isFinite(c.credits)) ||
       payload.job_courses.some(r=>!r.course_id||!r.job_id||!Number.isFinite(r.score)))
       throw Error('講義IDまたは関連スコアが不正です');
  }
  function replace(payload){
    validate(payload);
    for(const key of Object.keys(data)) data[key] = payload[key];
    courseNameMap = new Map(data.courses.map(c=>[simple(c.course_name),c.course_name]));
    if(window.RishuData) {
      window.RishuData.catalog.splice(0,window.RishuData.catalog.length,...data.courses.map(toCourse));
      document.dispatchEvent(new CustomEvent('rishu:datachange'));
    }
  }
  function toCourse(c){return {name:c.course_name,course_id:c.course_id,year:c.year,credits:c.credits,
    '講義名':c.course_name,'受講年次':String(c.year),'単位数':String(c.credits),
    '教育区分':c.education_category,'科目区分':c.subject_category_1,
    '科目区分１':c.subject_category_1,'科目区分２':c.subject_category_2,'詳細区分':c.subject_category_2,
    '履修前提科目':c.prerequisites.join('、'),'必修選択区分':c.requirement_type};}
  function load(){
    if(!promise) promise=(async()=>{
      try{
        // When launched through app_server.py, always use the backend's current CSV records.
        const r=await fetch('/api/catalog',{cache:'no-store'});
        if(!r.ok) throw Error('API HTTP '+r.status);
        replace(await r.json());source='バックエンドAPI';
      }catch(e){console.warn('Backend catalog unavailable: using the bundled database snapshot.',e);}
      return data;
    })();
    return promise;
  }
  function jobMatrix(){
    const jobs=data.jobs.filter(j=>j.job_name!=='特に決まっていない');
    const score=new Map(data.job_courses.map(r=>[r.job_id+'|'+r.course_id,Number(r.score)||0]));
    return [','+jobs.map(j=>j.job_name).join(','),...data.courses.map(c=>[c.course_name,...jobs.map(j=>score.get(j.job_id+'|'+c.course_id)||0)].join(','))].join('\n');
  }
  function qualificationRelations(){
    const qmap=new Map(data.qualifications.map(q=>[q.qualification_id,q]));
    const cmap=new Map(data.courses.map(c=>[c.course_id,c]));
    const jmap=new Map(data.jobs.map(j=>[j.job_id,j]));
    const jobsByQ=new Map();
    for(const rel of data.job_qualifications){
      if(!jobsByQ.has(rel.qualification_id))jobsByQ.set(rel.qualification_id,[]);
      jobsByQ.get(rel.qualification_id).push(jmap.get(rel.job_id)?.job_name||'');
    }
    const rows=['職業,資格,関連度の高い講義'];
    for(const rel of data.qualification_courses){
      const q=qmap.get(rel.qualification_id),c=cmap.get(rel.course_id);
      if(!q||!c)continue;
      for(const job of jobsByQ.get(rel.qualification_id)||['']) rows.push([job,q.qualification_name,c.course_name].join(','));
    }
    return rows.join('\n');
  }
  return {data,load,canonicalName,toCourse,jobMatrix,qualificationRelations,get source(){return source}};
})();
window.RishuData = (() => {
  const bridge=window.RishuBackend;
  const catalog=bridge.data.courses.map(bridge.toCourse);
  const norm=x=>String(bridge.canonicalName(x)||'').normalize('NFKC').replace(/[\s\u3000・（）()\-]/g,'').replace(/および/g,'及び').toLowerCase();
  function parse(csv){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<csv.length;i++){const x=csv[i];if(x==='"'){if(quote&&csv[i+1]==='"'){cell+='"';i++}else quote=!quote;}else if(x===','&&!quote){row.push(cell);cell='';}else if((x==='\n'||x==='\r')&&!quote){if(x==='\r'&&csv[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v))rows.push(row);row=[];cell='';}else cell+=x}if(cell||row.length){row.push(cell);rows.push(row)}const header=rows.shift()||[];return rows.map(r=>Object.fromEntries(header.map((h,i)=>[h,r[i]||''])))}
  function history(){try{const x=JSON.parse(localStorage.getItem('history')||'[]');return Array.isArray(x)?x:[]}catch{return []}}
  function period(r){return (r?.periods||r?.selectedPeriods||[])[0]||r?.period||''}
  const periodRank=p=>{const m=String(p||'').match(/([1-4])年(前期|後期)/);return m?Number(m[1])*2+(m[2]==='後期'?1:0):0};
  function latest(){return history().slice().sort((a,b)=>periodRank(period(a))-periodRank(period(b))).at(-1)||null}
  function completed(){const h=latest();const list=h?.subjects||h?.selectedLectures||h?.lectures||[];return new Set(list.map(x=>norm(typeof x==='string'?x:x?.name)))}
  const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback}catch{return fallback}};
  const save=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
  return {catalog,parse,norm,history,period,latest,completed,read,save};
})();
window.rishuLoadCSV = async function(name){
  await window.RishuBackend.load();
  if(name==='data.csv')return window.RishuBackend.jobMatrix();
  if(name==='data1.csv')return window.RishuBackend.qualificationRelations();
  throw Error('未対応データ：'+name);
};
